// News API Results
const newsItems = $input.first().json.articles || [];

// HackerNews Results
const hnItems = $input.item.json.hits || [];

// Reddit Results
const redditItems = $input.item.json.data?.children?.map(c => c.data) || [];

// Merge and deduplicate
const allItems = [...newsItems, ...hnItems, ...redditItems].slice(0, 10);

return allItems.map(item => ({
  json: {
    title: item.title || item.story_title || '',
    url: item.url || item.story_url || ('https://news.ycombinator.com/item?id=' + item.objectID),
    source: item.source?.name || item._highlightResult?.author?.value || 'Reddit',
    points: item.points || 0,
    createdAt: item.createdAt || item.publishedAt || new Date().toISOString()
  }
}));

// Bewertung: 1-10 basierend auf Engagement
return $input.all().map(item => {
  const data = item.json;
  const points = data.points || 0;
  let score = 5;
  if (points > 100) score = 9;
  else if (points > 50) score = 8;
  else if (points > 10) score = 6;

  return {
    json: { ...data, relevanceScore: score }
  };
});

