// Strukturierte JSON für Blog-Post generieren
const item = $input.first().json;

return {
  json: {
    title: item.title,
    slug: item.title
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/(^-|-$)/g, '')
      .substring(0, 80),
    excerpt: item.excerpt || `Entdecke: ${item.title} - Eine der wichtigsten KI-Nachrichten heute.`,
    content: `<h2>${item.title}</h2><p>${item.excerpt || 'Hier erfährst du mehr über die neueste KI-Entwicklung.'}</p>`,
    category: 'news',
    tags: ['KI', 'News', 'AI', item.source],
    source: item.source,
    sourceUrl: item.url,
    publishedAt: new Date().toISOString()
  }
};

// YouTube-Video-Skript aus dem Blog-Post generieren
const post = $input.first().json;

const videoScript = `
TITEL: ${post.title}

INTRO (0-15 Sek):
"Hey Leute! Heute geht's um ${post.title}. Let's dive in!"

HAUPTTEIL (8-15 Min):
1. ${post.excerpt}
2. Warum das wichtig ist
3. Was die Konkurrenz macht
4. Fazit & Handlungsempfehlung

OUTRO:
"Abonniere für tägliche KI-News! Link in der Beschreibung."
`;

const shortsScript = `
${post.title} in 60 Sekunden! #AINews #KITools #Tech
`;

return {
  json: {
    ...post,
    videoScript,
    shortsScript,
    videoTags: ['#KI', '#AI', '#TechNews', '#KuenstlicheIntelligenz']
  }
};
